from contextlib import closing
import json
from pathlib import Path
import sqlite3
import subprocess
import sys
import tempfile
import unittest

import vault


WORKSPACE = Path(__file__).resolve().parent


class WriteIntegrityRegressions(unittest.TestCase):
    def database(self, setup='', encoding='UTF-8'):
        temporary = tempfile.TemporaryDirectory(dir=WORKSPACE)
        self.addCleanup(temporary.cleanup)
        path = Path(temporary.name) / 'vault.sqlite'
        with closing(sqlite3.connect(path)) as con:
            con.execute("PRAGMA encoding='" + encoding + "'")
            con.execute('CREATE TABLE observations(c,t,l)')
        vault.init_db(path)
        with closing(sqlite3.connect(path)) as con, con:
            con.executemany('INSERT INTO accounts VALUES (?,?,?)', [
                ('red', 'a', 100), ('red', 'b', 20), ('blue', 'private', 77),
                ('blue', 'other', 88),
            ])
            for table in ('transfers', 'audit'):
                con.executemany(f'INSERT INTO {table} VALUES (?,?,?,?,?)', [
                    ('red', 'previous', 'a', 'b', 1),
                    ('blue', 'previous', 'private', 'other', 1),
                ])
            con.executescript(setup)
        return path

    def snapshot(self, path):
        with closing(sqlite3.connect(path)) as con:
            result = {}
            for table, columns in (
                ('accounts', ('tenant', 'name', 'balance')),
                ('transfers', ('tenant', 'key', 'source', 'target', 'amount')),
                ('audit', ('tenant', 'key', 'source', 'target', 'amount')),
            ):
                # Include storage classes and bytes; malformed TEXT stays in
                # SQLite, and duplicate audit rows stay duplicated.
                fields = ','.join(f'typeof({col}),hex(CAST({col} AS BLOB))' for col in columns)
                result[table] = sorted(con.execute(f'SELECT {fields} FROM {table}').fetchall())
            result['schema'] = con.execute(
                'SELECT type,name,tbl_name,sql FROM sqlite_schema ORDER BY type,name'
            ).fetchall()
            result['observations'] = con.execute('SELECT * FROM observations').fetchall()
            return result

    def send(self, path):
        return vault.transfer(path, 'red', 'a', 'b', 10, 'new')

    def native_transfer(self, path):
        # Same public operation's four statements on a fresh native connection,
        # used only as a reference for trigger semantics and SQL-visible state.
        with closing(sqlite3.connect(path)) as con, con:
            con.execute('BEGIN IMMEDIATE')
            con.execute("UPDATE accounts SET balance=90 WHERE tenant='red' AND name='a'")
            con.execute("UPDATE accounts SET balance=30 WHERE tenant='red' AND name='b'")
            con.execute("INSERT INTO transfers VALUES ('red','new','a','b',10)")
            con.execute("INSERT INTO audit VALUES ('red','new','a','b',10)")

    def assert_native_control(self, setup, encoding='UTF-8'):
        native = self.database(setup, encoding)
        observed = self.database(setup, encoding)
        self.native_transfer(native)
        receipt = self.send(observed)
        self.assertEqual(receipt, dict(tenant='red', key='new', source='a', target='b', amount=10))
        self.assertEqual(self.snapshot(observed), self.snapshot(native))
        committed = self.snapshot(observed)
        self.assertEqual(self.send(observed), receipt)
        self.assertEqual(self.snapshot(observed), committed)

    def assert_rollback(self, setup):
        path = self.database(setup)
        before = self.snapshot(path)
        with self.assertRaises(sqlite3.IntegrityError):
            self.send(path)
        self.assertEqual(self.snapshot(path), before)
        self.assertEqual(vault.balance(path, 'red', 'a'), 100)
        return path

    def assert_native_api_cli(self, setup, abort=False):
        """Compare reopened state and exact schema through both public paths."""
        native = self.database(setup)
        before = self.snapshot(native)
        if abort:
            with self.assertRaises(sqlite3.IntegrityError):
                self.native_transfer(native)
            self.assertEqual(self.snapshot(native), before)
        else:
            self.native_transfer(native)
        expected = self.snapshot(native)
        receipt = dict(tenant='red', key='new', source='a', target='b', amount=10)
        paths = [native]
        for interface in ('api', 'cli'):
            path = self.database(setup)
            paths.append(path)
            if interface == 'api':
                if abort:
                    with self.assertRaises(sqlite3.IntegrityError):
                        self.send(path)
                else:
                    self.assertEqual(self.send(path), receipt)
                    self.assertEqual(self.send(path), receipt)  # durable replay
            else:
                for _ in range(1 if abort else 2):
                    result = subprocess.run(
                        [sys.executable, '-B', str(WORKSPACE / 'app.py'), str(path),
                         json.dumps(dict(op='transfer', **receipt))],
                        cwd=WORKSPACE, capture_output=True, text=True, timeout=15,
                    )
                    if abort:
                        self.assertEqual((result.returncode, result.stdout), (2, ''))
                        self.assertEqual(json.loads(result.stderr), {'error': 'invalid request'})
                        self.assertEqual(len(result.stderr.splitlines()), 1)
                    else:
                        self.assertEqual((result.returncode, result.stderr), (0, ''))
                        self.assertEqual(json.loads(result.stdout), receipt)
            self.assertEqual(self.snapshot(path), expected, interface)
            self.assertEqual(self.snapshot(path)['schema'], before['schema'])
            self.assertEqual(vault.balance(path, 'red', 'a'), 100 if abort else 90)
            self.assertEqual(vault.balance(path, 'red', 'b'), 20 if abort else 30)
        return paths

    def test_recursive_mode_parentheses_cte_scopes_and_qualified_columns(self):
        queries = (
            ('SELECT recursive_triggers FROM (pragma_recursive_triggers())', 0),
            ("SELECT recursive_triggers FROM ((\"main\".'pragma_recursive_triggers'()))", 0),
            ('SELECT p.recursive_triggers FROM ([pragma_recursive_triggers]) AS p', 0),
            ('SELECT main.pragma_recursive_triggers.recursive_triggers FROM main.pragma_recursive_triggers()', 0),
            ('SELECT main.p.recursive_triggers FROM (main.pragma_recursive_triggers() AS p)', 0),
            ('WITH pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) '
             'SELECT * FROM pragma_recursive_triggers', 7),
            ('WITH RECURSIVE "pragma_recursive_triggers"(recursive_triggers) AS MATERIALIZED (VALUES(7)) '
             'SELECT * FROM ("pragma_recursive_triggers")', 7),
            ('WITH first AS (SELECT * FROM pragma_recursive_triggers), '
             'pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) SELECT * FROM first', 7),
            ('WITH pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) '
             'SELECT * FROM (SELECT * FROM pragma_recursive_triggers)', 7),
            ('WITH pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) '
             'SELECT main.pragma_recursive_triggers.recursive_triggers FROM main.pragma_recursive_triggers()', 0),
            ('SELECT (WITH pragma_recursive_triggers(recursive_triggers) AS (VALUES(7)) '
             'SELECT * FROM pragma_recursive_triggers) + '
             '(SELECT recursive_triggers FROM pragma_recursive_triggers()) AS recursive_triggers', 7),
            ("SELECT recursive_triggers + length(printf('%s', 'pragma_recursive_triggers'))-25 "
             "AS recursive_triggers FROM ('pragma_recursive_triggers'())", 0),
        )
        for query, value in queries:
            for through_view in (False, True):
                for abort in (False, True):
                    with self.subTest(query=query, view=through_view, abort=abort):
                        setup = f'CREATE VIEW saved_mode AS {query};' if through_view else ''
                        read = 'SELECT recursive_triggers FROM saved_mode' if through_view else query
                        setup += f'''
                            CREATE TRIGGER native_guard BEFORE INSERT ON audit
                            WHEN ({read}){'=' if abort else '<>'}{value}
                            BEGIN SELECT RAISE(ABORT,'native guard'); END;
                        '''
                        self.assert_native_api_cli(setup, abort)

