from pathlib import Path
from contextlib import closing
import json, sqlite3, subprocess, sys, tempfile
import vault
root=Path.cwd()
request=dict(op='transfer',tenant='red',source='a',target='b',amount=10,key='new')
def snapshot(p):
    with closing(sqlite3.connect(p)) as c:
        return {t:c.execute('SELECT * FROM '+t+' ORDER BY rowid').fetchall() for t in ('accounts','transfers','audit','observations')} | {'schema':c.execute('SELECT type,name,sql FROM sqlite_schema ORDER BY type,name').fetchall()}
def native(p):
    with closing(sqlite3.connect(p)) as c, c:
        c.execute('BEGIN IMMEDIATE')
        for sql in (\"UPDATE accounts SET balance=90 WHERE tenant='red' AND name='a'\", \"UPDATE accounts SET balance=30 WHERE tenant='red' AND name='b'\", \"INSERT INTO transfers VALUES ('red','new','a','b',10)\", \"INSERT INTO audit VALUES ('red','new','a','b',10)\"):
            c.execute(sql)
with tempfile.TemporaryDirectory(dir=root) as temp:
    for timing in ('BEFORE','AFTER'):
        for abort in (True,False):
            results={}
            states={}
            for interface in ('native','api','cli','pre_cli'):
                p=Path(temp)/f'{timing}_{abort}_{interface}.db'
                vault.init_db(p)
                with closing(sqlite3.connect(p)) as c, c:
                    c.executemany('INSERT INTO accounts VALUES (?,?,?)',[('red','a',100),('red','b',20),('blue','p',77),('blue','q',88)])
                    c.executescript(f'''
                      CREATE TABLE observations(n,c,t);
                      CREATE TRIGGER guard {timing} UPDATE ON accounts WHEN OLD.tenant='blue' BEGIN
                        UPDATE accounts SET balance=balance WHERE tenant=OLD.tenant AND name=OLD.name;
                        INSERT INTO observations VALUES (OLD.name, changes(), total_changes());
                        SELECT CASE WHEN OLD.name='p' THEN RaIsE /* ignored row */( IgNoRe )
                          ELSE {\"RAISE(ABORT,'native guard')\" if abort else '0'} END;
                      END;
                      CREATE TRIGGER effect AFTER INSERT ON audit BEGIN
                        UPDATE accounts SET balance=balance WHERE tenant='blue';
                        INSERT INTO observations VALUES ('resumed',changes(),total_changes());
                      END;
                    ''')
                before=snapshot(p)
                try:
                    if interface=='native':
                        native(p)
                        outcome='ok'
                    elif interface=='api':
                        receipt=vault.transfer(p,'red','a','b',10,'new')
                        committed=snapshot(p)
                        assert vault.transfer(p,'red','a','b',10,'new')==receipt
                        assert snapshot(p)==committed
                        outcome='ok; replay unchanged'
                    else:
                        app=root/('.pre-repair/app.py' if interface=='pre_cli' else 'app.py')
                        result=subprocess.run([sys.executable,'-B',str(app),str(p),json.dumps(request)],capture_output=True,text=True,timeout=20,cwd=root)
                        outcome={'exit':result.returncode,'stdout':result.stdout.strip(),'stderr':result.stderr.strip()}
                except sqlite3.Error as e:
                    outcome=type(e).__name__+': '+str(e)
                after=snapshot(p)
                states[interface]=after
                results[interface]={'outcome':outcome,'unchanged':after==before,'accounts':after['accounts'],'audit_count':len(after['audit']),'observations':after['observations'],'schema_restored':after['schema']==before['schema']}
            assert states['native']==states['api']==states['cli'], results
            print(json.dumps({'timing':timing,'abort':abort,'results':results}))
PY"

